from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import combinations
import heapq


def _dependency_solver(data, name_order, preference):
    packages = data["packages"]
    names = sorted(packages, reverse=(name_order == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    best_vector = None
    best_versions = None

    def acyclic(edges):
        done = set()
        active = set()

        def visit(node):
            if node in active:
                return False
            if node in done:
                return True
            active.add(node)
            for child in edges.get(node, ()):
                if not visit(child):
                    return False
            active.remove(node)
            done.add(node)
            return True

        return all(visit(node) for node in edges)

    def search(requirements, chosen, edges):
        nonlocal best_vector, best_versions
        if any(name in chosen and not (low <= chosen[name] <= high)
               for name, (low, high) in requirements.items()):
            return
        pending = [name for name in requirements if name not in chosen]
        if not pending:
            if not acyclic(edges):
                return
            vector = tuple(chosen.get(name, -1) for name in names)
            better = (best_vector is None or
                      (vector < best_vector if preference == "minimum"
                       else vector > best_vector))
            if better:
                best_vector = vector
                best_versions = dict(chosen)
            return

        # Any variable order is complete; choosing the tightest domain prunes early.
        def candidates(name):
            low, high = requirements[name]
            rows = [row for row in packages.get(name, [])
                    if low <= row["version"] <= high
                    and row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
            return rows

        name = min(pending, key=lambda n: len(candidates(n)))
        low, high = requirements[name]
        for row in candidates(name):
            version = row["version"]
            next_chosen = dict(chosen)
            next_chosen[name] = version
            next_requirements = dict(requirements)
            next_edges = {key: list(value) for key, value in edges.items()}
            next_edges[name] = []
            valid = True
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                child = dep["name"]
                next_edges[name].append(child)
                dep_low, dep_high = dep["min"], dep["max"]
                if child in next_requirements:
                    old_low, old_high = next_requirements[child]
                    dep_low, dep_high = max(dep_low, old_low), min(dep_high, old_high)
                if dep_low > dep_high:
                    valid = False
                    break
                next_requirements[child] = (dep_low, dep_high)
                if child in next_chosen and not dep_low <= next_chosen[child] <= dep_high:
                    valid = False
                    break
            if valid:
                search(next_requirements, next_chosen, next_edges)

    roots = {name: (bounds[0], bounds[1])
             for name, bounds in data.get("roots", {}).items()}
    search(roots, {}, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _revision_ledger(data):
    mode = data["rounding"]

    def rounded(numerator):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(net * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _quota_intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    eligible = [job for job in jobs if job["id"] not in blocked]
    best_value = None
    best_ids = None

    if not mandatory.issubset({job["id"] for job in eligible}):
        return {"error": "impossible"}
    if k < 0 or k > len(eligible) or len(mandatory) > k:
        return {"error": "impossible"}

    for subset in combinations(eligible, k):
        ids = [job["id"] for job in subset]
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in subset)
        selected = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and selected < best_ids)):
            best_value, best_ids = value, selected

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _temporal_routes(data):
    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full_mask = (1 << len(required)) - 1
    start_node = data["source"]
    start_mask = bit_for.get(start_node, 0)
    start_state = (start_node, start_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"], start_node, start_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full_mask and remaining == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                options.append((duration, remaining - 1))
            for duration, next_remaining in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                next_state = (next_node, next_mask, next_remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_remaining))
    return {"arrival": None}


SOLVERS = {
    "component_01": lambda data: _dependency_solver(data, "ascending", "minimum"),
    "component_02": lambda data: _dependency_solver(data, "descending", "maximum"),
    "component_03": lambda data: _dependency_solver(data, "descending", "minimum"),
    "component_04": lambda data: _dependency_solver(data, "ascending", "maximum"),
    "component_05": lambda data: _dependency_solver(data, "ascending", "minimum"),
    "component_06": _revision_ledger,
    "component_07": _quota_intervals,
    "component_08": _temporal_routes,
}
